apiVersion: v1
kind: ConfigMap
metadata: {name: ap98-embedded-javascript}
data:
  reader.sh: |
    cat > /tmp/ap98-reader.mjs <<'JAVASCRIPT'
    const environment = process.env;
    const read = (name) => environment[name];
    process.stdout.write(read('AP98_EMBEDDED_YAML_HELPER') || '');
    JAVASCRIPT
